const [chapterData,maps,assets,government,cityData,portraitData,spatialData,geography,operatorData]=await Promise.all(['chapters.json','map-assets.json','assets.json','governance.json','cities.json','portrait-aliases.json','story-spatial.json','city-geography.json','operators.json'].map(p=>fetch(p).then(r=>{if(!r.ok)throw Error(p);return r.json();})));
