const state={mode:'atlas',base:'painted',region:null,chapter:0,node:0,zone:0,camera:{x:600,y:355,scale:1},animation:0,transitioning:false,sceneChapter:null,storyView:'tactical',pendingChapter:null};
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label,cls='source-link')=>url?`<a class="${cls}" href="${safe(url)}" target="_blank" rel="noopener noreferrer">${safe(label)} ↗</a>`:'';
function el(tag,attrs,parent){const n=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs||{}))n.setAttribute(k,v);parent?.append(n);return n;}
function txt(parent,value,x,y,cls){const t=el('text',{x,y,class:cls},parent);t.textContent=value;return t;}
function announce(t){$('#announcement').textContent=t;}
function imageFor(name){const aliases={'恩雅·希瓦艾什':'初雪','恩雅':'初雪','恩希欧迪斯·希瓦艾什':'银灰','恩希欧迪斯':'银灰','维娜':'维娜·维多利亚','Logos':'逻各斯'};const key=portraitData.aliases?.[name]||aliases[name]||name;const known=assets[name]||assets[key+'05.png']||assets[key];if(known)return known;const operator=operatorData.operators.find(o=>o.name===key||o.name===name);return operator?{path:operator.image,dimensions:[180,180]}:null;}
function portrait(name){const a=imageFor(name);const [iw,ih]=a?.dimensions||[a?.width,a?.height];if((portraitData.nonPortraitEntities||[]).includes(name))return '<span class="entity-label">权力机构</span>';if(a?.focusBox&&iw&&ih)return `<svg class="portrait-image" role="img" aria-label="${safe(name)}" viewBox="${a.focusBox.join(' ')}" preserveAspectRatio="xMidYMin slice"><title>${safe(name)}</title><image href="${safe(a.path)}" x="0" y="0" width="${iw}" height="${ih}"/></svg>`;return a?`<img src="${safe(a.path)}" alt="${safe(name)}" loading="lazy">`:`<span class="portrait-missing" aria-label="${safe(name)}肖像仍待核对"><span>◈</span><small>肖像待核对</small></span>`;}
function personCard(p){return `<article class="person-card${(portraitData.nonPortraitEntities||[]).includes(p.portraitQuery||p.name)?' entity-card':''}"><button class="person-portrait-button" data-person="${safe(p.name)}" aria-label="阅读${safe(p.name)}的站内介绍">${portrait(p.portraitFile||p.portraitQuery||p.name)}</button><div class="person-info"><h4>${safe(p.name)}${p.portraitQuery&&p.portraitQuery!==p.name?`<small>${safe(p.portraitQuery)}</small>`:''}</h4><p class="role">${safe(p.role||'相关人物')}</p>${p.period?`<p class="period">${safe(p.period)}</p>`:''}<button class="source-link" data-person="${safe(p.name)}">阅读站内档案 →</button></div></article>`;}
function openDetails(){document.body.classList.add('details-open');$('#details').hidden=false;}
function closeDetails(){document.body.classList.remove('details-open');$('#details').hidden=true;state.region=null;renderAtlas();if(state.mode==='atlas')setCamera({x:600,y:355,scale:homeScale()});}
const homeScale=()=>matchMedia('(max-width:720px)').matches?1.7:1;
function viewHeight(){const box=$('#map-stage').getBoundingClientRect();return Math.max(1,1200*box.height/Math.max(1,box.width));}
function setCamera(c){state.camera=c;document.body.classList.toggle('map-detailed',c.scale>1.5);const vh=viewHeight();$('#map').setAttribute('viewBox',`0 0 1200 ${vh}`);$('#camera').setAttribute('transform',`translate(600 ${vh/2}) scale(${c.scale}) translate(${-c.x} ${-c.y})`);$('#zoom-label').textContent=Math.round(c.scale/(state.mode==='story'?navigationFocus().scale:1)*100)+'%';}
function tween(target,time,token,onFrame){return new Promise(resolve=>{const start={...state.camera},t0=performance.now();function frame(now){if(token!==state.animation)return resolve(false);const t=Math.min(1,(now-t0)/Math.max(1,time));setCamera(interpolateCamera(start,target,t));onFrame?.(t);if(t<1)requestAnimationFrame(frame);else resolve(true);}requestAnimationFrame(frame);});}
function transitionState(phase){$('#map-stage').dataset.phase=phase;state.transitioning=phase!=='idle';$('#map-stage').setAttribute('aria-busy',String(state.transitioning));document.body.classList.toggle('map-transitioning',state.transitioning);$('#transition-status').hidden=!state.transitioning;$('#transition-status').textContent=({exiting:'收回上一章 · 返回泰拉',overview:'泰拉大陆 · 地区导航',entering:'定位 '+(regions.find(r=>r.id===destination(state.pendingChapter??state.chapter)?.region)?.name||'剧情档案'),revealing:'展开剧情行迹'})[phase]||'';document.querySelectorAll('#node-panel button,#zone-tabs button,.zoom button,#play-nodes,[data-story-view]').forEach(b=>b.disabled=state.transitioning);}
function renderStoryWorld(){const land=$('#land');if(land.querySelector('image')?.getAttribute('href')!==storyWorld.path){land.replaceChildren();el('image',{href:storyWorld.path,x:storyWorld.x,y:storyWorld.y,width:storyWorld.width,height:storyWorld.height,preserveAspectRatio:'xMidYMid meet'},land);}land.style.display='';$('#places').style.display='none';$('#markers').replaceChildren();}
function renderAtlas(){const land=$('#land'),places=$('#places');places.replaceChildren();const m=baseMaps[state.base];if(land.querySelector('image')?.getAttribute('href')!==m.path){land.replaceChildren();el('image',{href:m.path,x:m.x,y:m.y,width:m.width,height:m.height,preserveAspectRatio:'xMidYMid meet',class:'atlas-image'},land);}
 if(state.base!=='terra'){
  regions.forEach(r=>{const p=regionPoint(r.id)||specialPoints[r.id];if(!p)return;const [x,y]=p;const g=el('g',{'data-region':r.id,class:'region-label'+(state.region===r.id?' selected':''),tabindex:0,role:'button','aria-label':r.name+'：打开地区档案'},places);el('rect',{x:x-44,y:y-22,width:88,height:32,rx:3,fill:'transparent'},g);txt(g,r.name,x,y,'nation-name');txt(g,r.en||'',x,y+15,'nation-en');});
  const occupied=regions.map(r=>{const p=regionPoint(r.id)||specialPoints[r.id];if(!p)return null;const width=labelWidth(localize(r.name),18);return {x:p[0]-width/2,y:p[1]-22,width,height:27};}).filter(Boolean);
  const positioned=placeCityLabels(cityRecords.filter(c=>c.point).map(c=>({city:c,point:c.point,label:localize(c.geo?.label||c.name)})),occupied);
  positioned.forEach(({city:c,x:labelX,y:labelY,box})=>{const [x,y]=c.point;const g=el('g',{'data-city':c.name,class:'city-marker '+(c.geo?.accuracy==='region-only'?'city-index':'')+(state.region===c.region?' selected-region-city':''),tabindex:0,role:'button','aria-label':c.name+'：查看'+c.kind+'资料'},places);el('rect',{x:box.x,y:box.y,width:box.width,height:box.height,fill:'transparent'},g);if(Math.abs(labelY-y-4)>5||Math.abs(labelX-x-12)>5)el('path',{d:`M${x},${y} L${labelX-4>x?labelX-3:labelX+box.width-7},${labelY-5}`,class:'city-line'},g);if(c.geo?.accuracy==='region-only')el('rect',{x:x-4,y:y-4,width:8,height:8,rx:1,class:'index-symbol'},g);else{el('circle',{cx:x,cy:y,r:3.4},g);el('circle',{cx:x,cy:y,r:7,fill:'none','stroke-opacity':.3},g);}txt(g,c.geo?.label||c.name,labelX,labelY,'city-name');const tip=el('title',{},g);tip.textContent=c.kind+' · '+(c.geo?.accuracy==='relative'?'来源支持的相对方位':'所属地区索引，城市具体位置未确认')+' · '+c.geo?.basis;});
 }
 $('#map-basemaps').innerHTML=Object.entries(baseMaps).map(([id,m])=>`<button data-base="${id}" aria-pressed="${state.base===id}" class="${state.base===id?'active':''}">${m.label}</button>`).join('');$('#map-credit').innerHTML=link(m.source,m.caption);$('#region-strip').innerHTML=regions.map(r=>`<button data-region="${r.id}" class="${state.region===r.id?'active':''}">${r.name}</button>`).join('');$('#map-kind').textContent=matchMedia('(max-width:720px)').matches?'拖动探索 · ⌖ 查看全图':state.base==='painted'?'国家与城邦 · 编辑绘卷':'官方原始影像';
}
function renderRegion(id,cityName){if(cityName)return renderCity(cityName);const r=regions.find(r=>r.id===id);const city=cityRecords.find(c=>c.name===cityName);state.region=id;openDetails();$('#node-panel').hidden=true;$('#aside-title').textContent=cityName?'CITY ARCHIVE / 城邦档案':'REGION ARCHIVE / 地区档案';
 const title=cityName||r?.name||'地区';const people=r?.people||[];const ops=(r?.operators||[]).map(n=>typeof n==='string'?n:n.name);const heroName=id==='kjerag'?'初雪':id==='victoria'?'维娜·维多利亚':ops[0];const hero=assets['Pack_'+heroName+'_skin_0_0.png'];
 const localCities=cityRecords.filter(c=>c.region===id);const chapterIDs=cityName?chapters.filter(c=>c.place.includes(cityName)||c.nodes.some(n=>n.place.includes(cityName))).map(c=>c.id):r?.chapters||[];
 $('#detail-content').innerHTML=`<div class="archive-hero">${hero?`<img src="${safe(hero.path)}" alt="${safe(heroName)}官方立绘">`:''}<div><span class="eyebrow">${safe(r?.en||'CITY FILE')}</span><h2>${safe(title)}</h2><p>${safe(cityName?r?.name||'独立城市':'TERRA / 地区档案')}</p></div></div><p class="desc">${safe(cityName?city?.locationNote:r?.summary||r?.description)}</p>${city?`<div class="fact-note">点位依据：${safe(city.locationNote)}${link(city.source,'城邦资料')}</div>`:''}<div class="section-title">${cityName?'所属地区的治理人物':'治理人物与权力机构'}<span>${people.length} 条</span></div><p class="tiny">职务与时期分列；地方统治者、议会、宗教领袖与军方不混为同一职位。</p><div class="people-grid">${people.map(personCard).join('')||'<p class="fact-note">公开资料未给出可确认的具名全国统治者；本地区的机构与地方权力资料见来源。</p>'}</div><div class="section-title">相关人物<span>${ops.length}</span></div><div class="operator-grid">${ops.map(n=>`<button class="operator-card" data-person="${safe(n)}">${portrait(n)}<span>${safe(n)}</span></button>`).join('')}</div><div class="section-title">城邦与聚落</div><div class="city-list">${localCities.map(c=>`<button data-city="${c.name}"><span>◉</span> ${c.name} <span>↗</span></button>`).join('')}</div><div class="section-title">相关主线</div>${chapterIDs.map(n=>`<button class="chapter-link" data-chapter="${n}"><span>${String(n).padStart(2,'0')}</span>${chapters[n].title}<span>↗</span></button>`).join('')||'<p class="tiny">该地区未建立主线章节关联；相关人物档案仍可阅读。</p>'}<div class="section-title">资料来源</div>${link(sources[r?.source]?.url||r?.source||`https://wiki.biligame.com/arknights/${encodeURIComponent(r?.name||title)}`,'地区资料')}`;
 renderAtlas();const focus=city?.point||regionPoint(id)||specialPoints[id];if(focus)setCamera({x:Math.max(320,Math.min(900,focus[0])),y:Math.max(240,Math.min(470,focus[1]+25)),scale:1.55});announce('打开'+title+'档案');
}
function renderCity(name){const city=cityRecords.find(c=>c.name===name);if(!city)return;const r=regions.find(r=>r.id===city.region);state.region=city.region;openDetails();$('#node-panel').hidden=true;$('#aside-title').textContent='CITY ARCHIVE / '+city.kind+'档案';const people=(city.people||[]).map(p=>typeof p==='string'?regions.flatMap(r=>r.people||[]).find(x=>x.name===p):p).filter(Boolean);const ops=city.operators||[];const names=[city.name,...(city.aliases||[])];const chapterIDs=chapters.filter(c=>names.some(n=>c.place.includes(n)||c.nodes.some(e=>e.place.includes(n))));$('#detail-content').innerHTML=`<div class="archive-hero city-hero"><div><span class="eyebrow">${safe(city.kind)} / ${safe(r?.name||'独立城市')}</span><h2>${safe(city.name)}</h2>${city.aliases?.length?`<p>亦称 ${safe(city.aliases.join('、'))}</p>`:''}</div></div><p class="desc city-summary">${safe(city.summary)}</p><div class="fact-note"><strong>地理与归属</strong><p>${safe(city.locationNote)}</p><p>${safe(city.geo?.basis||'方位未确认，仅收录地点资料。')}</p></div>${people.length?`<div class="section-title">与此地有关的治理人物</div><div class="people-grid">${people.map(personCard).join('')}</div>`:''}${ops.length?`<div class="section-title">与此地有关的人物</div><div class="operator-grid">${ops.map(n=>`<button class="operator-card" data-person="${safe(n)}">${portrait(n)}<span>${safe(n)}</span></button>`).join('')}</div>`:''}${chapterIDs.length?`<div class="section-title">相关主线章节</div>${chapterIDs.map(c=>`<button class="chapter-link" data-chapter="${c.id}"><span>${String(c.id).padStart(2,'0')}</span>${safe(c.title)}<span>↗</span></button>`).join('')}`:''}<div class="section-title">城市资料来源</div>${city.sources.map(s=>link(s.url,s.title)).join('')}${r?`<button class="chapter-link" data-region="${r.id}">查看${safe(r.name)}地区档案 <span>↗</span></button>`:''}`;renderAtlas();const focus=city.point||regionPoint(city.region)||specialPoints[city.region];if(focus)setCamera({x:Math.max(300,Math.min(920,focus[0])),y:Math.max(230,Math.min(470,focus[1])),scale:1.55});$('#details').scrollTop=0;announce('打开'+city.name+'独立档案');}
function currentMaps(){return maps.filter(m=>m.chapter===state.chapter);}
function boardSize(){const width=matchMedia('(max-width:720px)').matches?720:1200;return {width,height:width*viewHeight()/1200};}
function navigationFocus(id=state.chapter){const d=destination(id);if(state.storyView==='reference'&&d)return {x:d.point[0],y:d.point[1],scale:Math.min(1200/(1240*.14),(viewHeight()-30)/(740*.14))};return focusCamera(id,viewHeight(),matchMedia('(max-width:720px)').matches);}
function sceneAnchor(layer){const d=destination(state.chapter),size=state.storyView==='tactical'?boardSize():{width:1200,height:740};const fitted=Math.min(1200/(size.width+36),(viewHeight()-20)/size.height);layer.setAttribute('transform',d?sceneTransform(d.point,size.width,size.height):`translate(600 342) scale(${fitted/overviewCamera(viewHeight()).scale}) translate(${-size.width/2} ${-size.height/2})`);layer.dataset.chapter=state.chapter;state.sceneChapter=state.chapter;}
function renderLocal({reuse=false}={}){const layer=$('#local-map'),c=chapters[state.chapter],n=c.nodes[state.node],list=currentMaps(),m=list[state.zone]||list[0];sceneAnchor(layer);
 if(state.storyView==='tactical'){
  if(!reuse||!tactical||tactical.spatial.id!==state.chapter){layer.replaceChildren();tactical=createTacticalMap(layer,c,spatialData.chapters[state.chapter],imageFor,{compact:matchMedia('(max-width:720px)').matches,onActor:selectActor,...boardSize()});}
  activePlacements=tactical.update(state.node,{animate:reuse&&!matchMedia('(prefers-reduced-motion:reduce)').matches});$('#zone-tabs').hidden=true;$('#map-credit').innerHTML=link(n.sources[0]?.url,'地点与势力依据 · 游戏原文');
 }else{layer.replaceChildren();tactical=null;el('rect',{x:20,y:40,width:1160,height:660,rx:8,fill:'#122a35'},layer);if(m)el('image',{href:m.path,x:45,y:65,width:1110,height:540,preserveAspectRatio:'xMidYMid meet'},layer);txt(layer,'官方素材参考 · 返回「行迹地图」查看势力位置',55,642,'scene-kind');txt(layer,n.place,55,677,'scene-place');$('#zone-tabs').hidden=list.length<2;$('#zone-tabs').innerHTML=list.map((m,i)=>`<button data-zone="${i}" class="${i===state.zone?'active':''}">${safe(m.label.replace('官方选关图','场景'))}</button>`).join('');$('#map-credit').innerHTML=link(m?.filepage||m?.source,'官方游戏素材 · 来源');}
 document.querySelectorAll('[data-story-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.storyView===state.storyView)));$('#map-kind').textContent='CHAPTER '+String(c.id).padStart(2,'0');$('#story-legend').hidden=state.storyView!=='tactical';
}
function selectActor(key){if(state.transitioning||!tactical)return;const p=tactical.select(key);if(!p)return;const panel=$('#actor-inspector');panel.hidden=false;panel.innerHTML=`<button class="inspector-close" aria-label="关闭小队情报">×</button><span class="eyebrow">${safe(relationLabels[p.relation]||'地点示意')}</span><h3>${safe(p.name)}</h3><p><strong>◉ ${safe(p.anchor.label)}</strong></p><p>${safe(p.characters.join(' / ')||'原文未具名小队')}</p><small>${safe(p.note)}</small>${link(p.sources?.[0]?.url||chapters[state.chapter].nodes[state.node].sources[0]?.url,'查看位置依据')}`;panel.querySelector('button').onclick=()=>{panel.hidden=true;tactical.select(null);};document.querySelectorAll('.faction-card').forEach((e,i)=>e.classList.toggle('selected',i===spatialData.chapters[state.chapter].nodes[state.node].placements.findIndex(item=>item.key===p.key)));}
function stopPlayback(){clearTimeout(nodePlayback);nodePlayback=null;$('#play-nodes').setAttribute('aria-pressed','false');$('#play-nodes').textContent='▶ 播放节点';}
function selectNode(index,{play=false}={}){if(state.transitioning||!chapters[state.chapter].nodes[index])return;if(!play)stopPlayback();$('#actor-inspector').hidden=true;state.node=index;renderStory();renderLocal({reuse:true});announce(chapters[state.chapter].nodes[index].title);}
function playNodes(){if(nodePlayback){stopPlayback();return;}const step=()=>{if(state.node>=chapters[state.chapter].nodes.length-1){stopPlayback();return;}selectNode(state.node+1,{play:true});$('#play-nodes').setAttribute('aria-pressed','true');$('#play-nodes').textContent='Ⅱ 暂停';nodePlayback=setTimeout(step,2400);};if(state.node===chapters[state.chapter].nodes.length-1)selectNode(0);$('#play-nodes').setAttribute('aria-pressed','true');$('#play-nodes').textContent='Ⅱ 暂停';nodePlayback=setTimeout(step,2400);}
function renderStory(){const c=chapters[state.chapter],n=c.nodes[state.node],placements=spatialData.chapters[state.chapter].nodes[state.node].placements;openDetails();$('#close-details').hidden=true;$('#aside-title').textContent='STORY ARCHIVE / 剧情档案';$('#node-panel').hidden=false;$('#node-panel').innerHTML=`<span class="node-strip-label">本章节点</span>${c.nodes.map((n,i)=>`<button data-node="${i}" class="${i===state.node?'active':''}" aria-pressed="${i===state.node}"><small>${String(i+1).padStart(2,'0')}</small>${safe(n.title)}</button>`).join('')}`;
 $('#detail-content').innerHTML=`<span class="eyebrow">EPISODE ${String(c.id).padStart(2,'0')}</span><h2>${safe(c.title)}</h2><p class="desc">${safe(c.summary)}</p><div class="section-title">${safe(n.title)}</div><span class="event-stage"><span>${safe(n.stage)}</span> <span>${safe(n.stageName||'')}</span></span><p class="desc">${safe(n.summary)}</p><div class="fact-note"><strong>◉ ${safe(n.place)}</strong><p>${safe(c.chronologyNote||n.time||'节点按剧情阅读顺序排列。')}</p></div>${c.id===17?'<p class="tiny">本章按原文绘制地点关系图；「官方参考」可对照已有乌萨斯区域素材。</p>':''}<div class="section-title">在场人物与势力</div><div class="story-actors">${placements.map((f,i)=>`<button class="faction-card" data-focus-team="${i}"><div class="faction-portraits">${f.characters.slice(0,2).map(p=>portrait(p)).join('')}</div><div><h4>${safe(f.name)}</h4><p>${safe(f.characters.join(' / ')||'原文未具名部队')}</p><small>◉ ${safe(f.sourceLocation)}</small></div></button>`).join('')}</div><p class="tiny">点击图上角色或小队卡查看地点依据。实线指向地点，点线表示剧情出场顺序（非道路），箭头虚线表示有原文支持的转移；回忆与远程联络单独标识。</p><div class="section-title">原文证据</div>${n.sources.map(s=>link(s.url,s.title)).join('')}`;
 $('#chapter-label').innerHTML=`<span>${String(c.id).padStart(2,'0')}</span> <span>${safe(c.title)}</span>`;$('#map-title').textContent=c.title;$('#map-subtitle').textContent=c.place;$('#chapter-range').value=String(c.id);$('#chapter-range').setAttribute('aria-valuetext',c.title);document.querySelectorAll('#chapter-buttons button').forEach(b=>{b.classList.toggle('active',+b.dataset.chapter===c.id);b.setAttribute('aria-pressed',String(+b.dataset.chapter===c.id));});$('#prev').disabled=c.id===0;$('#next').disabled=c.id===17;
}
const sceneLoads=new Map();
function preloadScene(id){if(!sceneLoads.has(id))sceneLoads.set(id,Promise.all(maps.filter(m=>m.chapter===id).map(m=>new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(true);img.onerror=()=>resolve(false);img.src=m.path;}))));return sceneLoads.get(id);}
async function selectChapter(id){if(!Number.isInteger(id)||!chapters[id])return;stopPlayback();$('#actor-inspector').hidden=true;const token=++state.animation;state.pendingChapter=id;const from=state.sceneChapter,near=from!==null&&destination(from)?.region===destination(id)?.region&&destination(id)!==null;const ready=preloadScene(id),reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;$('#chapter-label').textContent='正在定位 · '+String(id).padStart(2,'0')+' '+chapters[id].title;$('#chapter-range').value=id;
 const oldOpacity=Number($('#local-map').style.opacity||1),oldLandOpacity=Number($('#land').style.opacity||1);renderStoryWorld();transitionState('exiting');const wide=near?{x:destination(id).point[0],y:destination(id).point[1],scale:1.8}:overviewCamera(viewHeight());
 if(!await tween(wide,reduce?1:near?310:480,token,t=>{$('#local-map').style.opacity=String(oldOpacity*(1-t));$('#land').style.opacity=String(oldLandOpacity+(1-oldLandOpacity)*t);}))return;
 transitionState('overview');if(!await tween(wide,reduce?1:near?60:120,token))return;await ready;if(token!==state.animation||state.mode!=='story')return;
 state.chapter=id;state.node=0;state.zone=0;renderLocal();$('#local-map').style.opacity='0';transitionState('entering');const target=destination(id)?navigationFocus(id):overviewCamera(viewHeight());
 if(!await tween(target,reduce?1:near?450:680,token,t=>{$('#local-map').style.opacity=String(Math.max(0,(t-.24)/.76));$('#land').style.opacity=String(1-t);}))return;
 $('#land').style.opacity='0';$('#local-map').style.opacity='1';state.pendingChapter=null;renderStory();transitionState('idle');announce('第'+id+'章 '+chapters[id].title);}
function renderSources(){const total=chapters.reduce((a,c)=>a+c.nodes.length,0);$('#sources-page').innerHTML=`<div class="sources-wrap"><span class="eyebrow">EDITORIAL & SOURCE ARCHIVE</span><h1>每一处地名，都有它的来处。</h1><p class="lead">地图美术、地理依据和人物资料分别标识。原图可直接对照，故事可以回到具体原文。</p><div class="source-grid"><article class="source-card"><h3>地理绘卷</h3><p>参考2020年《初探泰拉》的区域相对布局绘制，采用独立地形插画与可交互文字层。纹理为AI辅助美术，不是官方地形或精确行政边界。图上城邦标记为地区与剧情方位索引，移动城市没有永久坐标。</p>${link('art-provenance.json','绘图说明与提示词')}${link('cities.json','独立城市与地点档案')}${link('city-geography.json','城市方位逐项核查')}</article><article class="source-card"><h3>官方影像对照</h3><p>可切换初探和三探原始画面。两次发布的世界信息存在版本差异，初探构图不能当作最新的全球测绘图。阿戈尔与杜林仅以档案标签表示，不画海底或地下国界。</p>${link('https://www.bilibili.com/video/BV1Hy4y1r7k7/','初探泰拉 · 官方')}${link('https://www.bilibili.com/video/BV17W4y1E7hK/','三探泰拉 · 官方')}</article><article class="source-card"><h3>人物与治理</h3><p>每位人物分别标明职务与阶段，议会、宗教和地方权力不等同于唯一国家元首。头像和立绘采用可核对的游戏素材，没有公开图像的角色明确标识。</p>${link('governance.json','治理与人物来源')}${link('assets.json','头像与立绘来源')}${link('portrait-aliases.json','图片核验与尚缺清单')}</article><article class="source-card"><h3>主线档案</h3><p>0—17章共${total}个关键节点，保留关卡号与游戏脚本来源。选关图、剧情插画与地理图分开标识。行迹图按原文的地点关系重新绘制，恢复每个节点的势力与小队标记；坐标为阅读布局，回忆、远程联络与非地理空间单独标识。</p>${link('chapters.json','逐节点原文')}${link('story-spatial.json','势力地点与示意布局依据')}${link('map-assets.json','章节素材类别')}</article></div><article class="source-card"><h3>活动故事分类</h3><p>按国家、地区和组织提供活动阅读入口，补充故事导读、人物档案与同乐章前后篇。剧情回顾、常驻关卡和当前活动分别标注；具体开放状态与核对日期以活动故事页面为准。</p>${link('events.json','活动归类与逐项来源')}<button class="chapter-link" data-mode="events">打开活动故事 ↗</button></article><article class="source-card"><h3>干员出身地与种族</h3><p>2026年11月8日国服游戏档案快照，438 个可获得干员条目，更新至《时间啊，向前！》。作业平台采用产地字段；未公开种族保留原文，合作角色不默认属于罗德岛正式员工。</p>${link('operators.json','逐干员档案与原始数据来源')}<button class="chapter-link" data-mode="origins">打开干员档案 ↗</button></article><article class="source-card"><h3>小传与多语言</h3><p>每个可点击人物入口都有三句小传和原文来源。英文、日文名称优先对应已发行游戏文本；尚无官方本地化的资料使用本站暂译。译文由AI辅助整理并复核，不属于官方译本；原始资料图像保留原貌，访客留言保留原文。</p>${link('biographies.json','三句小传与来源')}${link('locales/provenance.json','译文整理说明')}${link('locales/provisional-names.json','尚未本地化的名称')}</article><h2>内容核查范围</h2><p>资料以游戏官方原文为优先，百科查阅限定Bilibili Wiki、维基百科、百度百科、萌娘百科。脚本或图像镜像仅为原始游戏素材的托管来源，不视为官方运营网站。</p><p>全城市资料、未公开的精确坐标、全支线逐关路线及第17章专属细图仍有缺口。本站与鹰角网络无隶属关系，内部审查不等于官方认证。</p><button class="chapter-link" data-mode="atlas">返回地图 ↗</button></div>`;}
const guestbook=createGuestbookPage($('#guestbook-page'),{translate:localize});
guestbook.setLocale(currentLanguage());
