$('#operators-page').addEventListener('operator-mode',e=>setMode(e.detail));
function setMode(mode){if(!['atlas','story','sources','events','leaders','origins','races','guestbook'].includes(mode))return;stopPlayback();$('#actor-inspector').hidden=true;state.mode=mode;++state.animation;transitionState('idle');document.body.classList.toggle('story-mode',mode==='story');$('#workspace').hidden=['sources','events','leaders','origins','races','guestbook'].includes(mode);$('#operators-page').hidden=!['origins','races'].includes(mode);$('#leaders-page').hidden=mode!=='leaders';$('#events-page').hidden=mode!=='events';$('#sources-page').hidden=mode!=='sources';$('#guestbook-page').hidden=mode!=='guestbook';$('#timeline').hidden=mode!=='story';$('#map-basemaps').hidden=mode!=='atlas';$('#story-tools').hidden=mode!=='story';$('#story-legend').hidden=mode!=='story';$('#region-strip').hidden=mode!=='atlas';$('#map-search').closest('label').hidden=mode!=='atlas';$('#search-results').hidden=true;$('#close-details').hidden=mode==='story';document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-current',b.dataset.mode===mode?'page':'false');});history.replaceState(null,'','#'+mode);
 if(mode==='atlas'){state.sceneChapter=null;tactical=null;$('#land').style.opacity='1';$('#local-map').style.opacity='1';$('#local-map').removeAttribute('transform');$('#local-map').replaceChildren();$('#markers').replaceChildren();$('#land').style.display='';$('#places').style.display='';$('#zone-tabs').hidden=true;$('#node-panel').hidden=true;$('#map-title').textContent='泰拉大陆';$('#map-subtitle').textContent='初探布局 / 2020 · 国家与城邦';$('#eyebrow').textContent='EXPLORE TERRA';closeDetails();setCamera({x:600,y:355,scale:homeScale()});}
 if(mode==='story'){$('#eyebrow').textContent='MAIN THEME / 剧情行迹';renderStory();selectChapter(state.chapter);}
 if(['origins','races'].includes(mode))operatorPage.render(mode);if(mode==='leaders')leaders.render();if(mode==='sources')renderSources();if(mode==='events')renderEvents();if(mode==='guestbook')guestbook.render();
}
document.addEventListener('error',e=>{const img=e.target;if(!(img instanceof HTMLImageElement))return;const fallback=document.createElement('span');fallback.className='portrait-missing';fallback.setAttribute('role','img');fallback.setAttribute('aria-label',img.alt+'图片暂不可用');fallback.textContent='图片暂不可用';img.replaceWith(fallback);},true);
$('#chapter-buttons').innerHTML=chapters.map(c=>`<button data-chapter="${c.id}" aria-label="第${c.id}章 ${c.title}" title="${c.title}">${String(c.id).padStart(2,'0')}</button>`).join('');
document.addEventListener('click',e=>{if(e.target.closest('.brand')){e.preventDefault();setMode('atlas');return;}const find=k=>e.target.closest(`button[data-${k}],g[role="button"][data-${k}]`);let t;if(t=find('person')){const op=operatorData.operators.find(o=>o.name===t.dataset.person);return op?operatorPage.open(op.id):leaders.open(t.dataset.person);}if(t=find('mode'))return setMode(t.dataset.mode);if(t=find('base')){state.base=t.dataset.base;renderAtlas();setCamera({x:600,y:355,scale:homeScale()});return;}if(t=find('chapter')){if(state.mode==='story')selectChapter(+t.dataset.chapter);else{state.chapter=+t.dataset.chapter;setMode('story');}return;}if(t=find('region')){if(state.mode!=='atlas')setMode('atlas');$('#search-results').hidden=true;renderRegion(t.dataset.region);return;}if(t=find('city')){const c=cityRecords.find(c=>c.name===t.dataset.city);if(c){if(state.mode!=='atlas')setMode('atlas');renderRegion(c.region,c.name);$('#search-results').hidden=true;}return;}if(t=find('node'))return selectNode(+t.dataset.node);if(t=find('focus-team'))return selectActor(spatialData.chapters[state.chapter].nodes[state.node].placements[+t.dataset.focusTeam]?.key);if(t=find('story-view')){if(state.transitioning)return;stopPlayback();state.storyView=t.dataset.storyView;renderLocal();setCamera(destination(state.chapter)?navigationFocus():overviewCamera(viewHeight()));return;}if(t=find('zone')){if(state.transitioning)return;state.zone=+t.dataset.zone;renderLocal();}});
$('#close-details').onclick=closeDetails;let scrubTimer;$('#chapter-range').oninput=e=>{clearTimeout(scrubTimer);const id=+e.target.value;$('#chapter-label').innerHTML=`<span>${String(id).padStart(2,'0')}</span> <span>${safe(chapters[id].title)}</span>`;scrubTimer=setTimeout(()=>selectChapter(id),100);};$('#play-nodes').onclick=playNodes;$('#toggle-trails').onclick=()=>{const hide=document.body.classList.toggle('hide-trails');$('#toggle-trails').setAttribute('aria-pressed',String(!hide));$('#toggle-trails').textContent=hide?'轨迹 关':'轨迹 开';};$('#prev').onclick=()=>selectChapter((state.pendingChapter??state.chapter)-1);$('#next').onclick=()=>selectChapter((state.pendingChapter??state.chapter)+1);
function zoom(f){if(state.transitioning)return;++state.animation;setCamera({...state.camera,scale:Math.max(.35,Math.min(state.mode==='story'?navigationFocus().scale*2.5:4,state.camera.scale*f))});}$('#zoom-in').onclick=()=>zoom(1.2);$('#zoom-out').onclick=()=>zoom(1/1.2);$('#reset-map').onclick=()=>{if(state.transitioning)return;if(state.mode==='story'){const d=destination(state.chapter);setCamera(d?navigationFocus():overviewCamera(viewHeight()));}else setCamera({x:600,y:355,scale:homeScale()});};
$('#map').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.closest('[role="button"]')){e.preventDefault();e.target.closest('[role="button"]').dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
let drag;$('#map').onpointerdown=e=>{if(state.transitioning||e.button||e.target.closest('[role="button"]'))return;drag={x:e.clientX,y:e.clientY,c:{...state.camera},unit:$('#map').getScreenCTM().a};$('#map').setPointerCapture(e.pointerId);};$('#map').onpointermove=e=>{if(!drag)return;setCamera({...drag.c,x:drag.c.x-(e.clientX-drag.x)/drag.unit/drag.c.scale,y:drag.c.y-(e.clientY-drag.y)/drag.unit/drag.c.scale});};$('#map').onpointerup=$('#map').onpointercancel=()=>drag=null;$('#map').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?.94:1.06);},{passive:false});
$('#map-search').oninput=e=>{const q=e.target.value.trim(),panel=$('#search-results');panel.hidden=!q;if(!q)return;const rs=regions.filter(r=>searchable([r.name,...(r.operators||[]),...(r.people||[]).map(p=>p.name)],q));const cs=cityRecords.filter(c=>searchable([c.name,...(c.aliases||[])],q));panel.innerHTML=rs.map(r=>`<button class="search-result" data-region="${r.id}">${r.name}<small>地区 / 人物档案</small></button>`).join('')+cs.map(c=>`<button class="search-result" data-city="${c.name}">${c.name}<small>${c.kind}</small></button>`).join('')||'<p>暂未收录此条目。</p>';};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){$('#search-results').hidden=true;if(state.mode==='atlas')closeDetails();}});
new ResizeObserver(([entry])=>document.documentElement.style.setProperty('--topbar-height',entry.target.getBoundingClientRect().height+'px')).observe(document.querySelector('.topbar'));
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next!==state.mode)setMode(next);});
let previousNarrow=matchMedia('(max-width:720px)').matches;new ResizeObserver(()=>{const narrow=matchMedia('(max-width:720px)').matches;if(narrow!==previousNarrow&&state.mode==='story'&&!state.transitioning)renderLocal();if(narrow!==previousNarrow&&state.mode==='atlas'){state.camera={x:600,y:355,scale:narrow?1.7:1};}previousNarrow=narrow;if(state.mode==='story'&&!state.transitioning){renderLocal();setCamera(destination(state.chapter)?navigationFocus():overviewCamera(viewHeight()));}else setCamera(state.camera);}).observe($('#map-stage'));renderAtlas();setMode(['story','sources','events','leaders','origins','races','guestbook'].includes(location.hash.slice(1))?location.hash.slice(1):'atlas');

